const form = $('Search Criteria').first().json;
const role = String(form['Target Role'] || '').trim();
const skillsRaw = form['Key Skills & Criteria'] || '';
const loc = String(form['Location'] || '').split('-')[0].trim();
const excludeRaw = form['Keywords to Exclude'] || '';
const employer = String(form['Current Employer'] || '').trim();
const education = String(form['Education'] || '').trim();
const expand = String(form['Expand Job Title Synonyms'] || '').toLowerCase();

function q(s) { return /\s/.test(s) ? '"' + s + '"' : s; }
// A field "looks boolean" when the recruiter has already written their own
// query syntax (AND / OR / quoted phrases / minus). In that case we trust it
// verbatim and DO NOT wrap it in another pair of quotes (that nested-quote
// wrapping is what produced 0-result searches before).
function looksBoolean(s) {
  s = String(s);
  return /\s(OR|AND)\s/i.test(s) || s.indexOf('"') !== -1 || /(^|\s)-\w/.test(s);
}

// --- role: honour recruiter boolean, else quote + optional synonym expansion ---
const synMap = {
  'software engineer': ['software engineer','software developer','sde','backend engineer','full stack developer'],
  'backend engineer': ['backend engineer','back end engineer','software engineer','java developer','backend developer'],
  'frontend engineer': ['frontend engineer','front end engineer','ui engineer','react developer','javascript developer'],
  'full stack developer': ['full stack developer','fullstack developer','software engineer','web developer'],
  'data scientist': ['data scientist','machine learning engineer','ml engineer','ai engineer'],
  'data engineer': ['data engineer','big data engineer','etl developer','analytics engineer'],
  'data analyst': ['data analyst','business analyst','bi analyst'],
  'product manager': ['product manager','product owner','program manager','technical product manager'],
  'devops engineer': ['devops engineer','site reliability engineer','sre','platform engineer','infrastructure engineer'],
  'qa engineer': ['qa engineer','sdet','test engineer','automation engineer','quality engineer'],
  'designer': ['designer','ux designer','ui designer','product designer','ui/ux designer'],
  'mobile developer': ['mobile developer','android developer','ios developer','react native developer'],
  'sales': ['sales','account executive','business development','bdm','sales manager','account manager','inside sales'],
  'marketing': ['marketing','digital marketing','marketing manager','growth marketer','performance marketing','brand manager'],
  'hr': ['hr','human resources','talent acquisition','recruiter','hr manager','people operations','hrbp'],
  'recruiter': ['recruiter','talent acquisition','technical recruiter','hr recruiter','sourcer'],
  'accountant': ['accountant','accounts','chartered accountant','ca','finance executive','accounts manager','audit'],
  'finance': ['finance','financial analyst','fp&a','finance manager','financial planning','financial controller'],
  'operations': ['operations','operations manager','ops','business operations','operations executive'],
  'customer success': ['customer success','customer success manager','csm','account manager','customer support'],
  'content writer': ['content writer','copywriter','content marketer','editor','technical writer'],
  'project manager': ['project manager','program manager','delivery manager','scrum master','pmo'],
  'business analyst': ['business analyst','ba','business systems analyst','functional consultant']
};
let roleTerm = '';
if (role) {
  if (looksBoolean(role)) {
    // recruiter wrote their own boolean expression -> use as-is, grouped
    roleTerm = '(' + role + ')';
  } else {
    let variants = ['"' + role + '"'];
    if (expand === 'yes' || expand === 'true') {
      const key = role.toLowerCase();
      if (synMap[key]) { variants = synMap[key].map(function(v){ return '"' + v + '"'; }); }
    }
    roleTerm = variants.length > 1 ? '(' + variants.join(' OR ') + ')' : variants[0];
  }
}

// --- skills: honour recruiter boolean, else comma-split into an OR group ---
let skillsTerm = '';
if (String(skillsRaw).trim()) {
  if (looksBoolean(skillsRaw)) {
    skillsTerm = '(' + String(skillsRaw).trim() + ')';
  } else {
    const skills = String(skillsRaw).split(',').map(function(s){return s.trim();}).filter(Boolean);
    if (skills.length) {
      const quoted = skills.map(q);
      skillsTerm = quoted.length > 1 ? '(' + quoted.join(' OR ') + ')' : quoted[0];
    }
  }
}

// --- exclude keywords ---
const excludes = String(excludeRaw).split(',').map(function(s){return s.trim();}).filter(Boolean);
const excludeTerm = excludes.map(function(s){ return '-' + q(s); }).join(' ');

// --- current employer ---
const employerTerm = employer ? q(employer) : '';

// --- education level: loose OR-group of common variants ---
const eduMap = {
  'bachelors / degree': ['bachelor','bachelors','"b.e"','"b.tech"','btech','bsc','"b.sc"','degree'],
  'masters': ['master','masters','"m.e"','"m.tech"','mtech','msc','"m.sc"'],
  'phd': ['phd','"ph.d"','doctorate'],
  'mba': ['mba','"m.b.a"']
};
let eduTerm = '';
if (education && !/^any$/i.test(education)) {
  const ekey = education.toLowerCase();
  const variants = eduMap[ekey];
  if (variants && variants.length) { eduTerm = '(' + variants.join(' OR ') + ')'; }
  else { eduTerm = q(education); }
}

// --- platform site: filters ---
let platforms = form['Target Platforms'];
if (!Array.isArray(platforms)) {
  platforms = platforms ? String(platforms).split(',').map(function(s){return s.trim();}).filter(Boolean) : [];
}
const siteMap = {
  'LinkedIn': ['site:linkedin.com/in/'],
  'Github': ['site:github.com'],
  'GitHub': ['site:github.com'],
  'X (Twitter)': ['site:twitter.com','site:x.com'],
  'Stack Overflow': ['site:stackoverflow.com/users'],
  'Dribbble': ['site:dribbble.com'],
  'Behance': ['site:behance.net'],
  'Hacker News': ['site:news.ycombinator.com']
};
const openWeb = platforms.some(function(pl){ return /google|open web/i.test(pl); });
let sites = [];
if (!openWeb) {
  for (const pl of platforms) {
    if (siteMap[pl]) { sites = sites.concat(siteMap[pl]); }
  }
  if (sites.length === 0) {
    sites = ['site:linkedin.com/in/','site:github.com','site:twitter.com','site:x.com'];
  }
}

// --- JD keyword extraction: pull distinctive keywords to strengthen the search ---
let jdText = '';
try { jdText = String($('Prep JD').first().json.jd_text || ''); } catch (e) { jdText = ''; }
let jdTerm = '';
if (jdText) {
  const STOP = {'the':1,'and':1,'for':1,'with':1,'you':1,'your':1,'our':1,'are':1,'will':1,'that':1,'this':1,'have':1,'has':1,'from':1,'not':1,'but':1,'all':1,'can':1,'who':1,'what':1,'when':1,'how':1,'why':1,'their':1,'they':1,'them':1,'about':1,'into':1,'over':1,'more':1,'most':1,'such':1,'per':1,'via':1,'etc':1,'role':1,'roles':1,'work':1,'working':1,'team':1,'teams':1,'years':1,'year':1,'experience':1,'experiences':1,'strong':1,'good':1,'great':1,'excellent':1,'ability':1,'skills':1,'skill':1,'knowledge':1,'understanding':1,'responsibilities':1,'requirements':1,'preferred':1,'plus':1,'must':1,'should':1,'including':1,'across':1,'within':1,'using':1,'help':1,'build':1,'building':1,'develop':1,'developing':1,'design':1,'designing':1,'candidate':1,'candidates':1,'company':1,'companies':1,'job':1,'jobs':1,'position':1,'positions':1,'looking':1,'join':1,'we':1,'us':1,'is':1,'to':1,'of':1,'in':1,'on':1,'as':1,'at':1,'be':1,'or':1,'an':1,'a':1,'by':1,'it':1,'if':1,'do':1,'up':1,'new':1,'like':1,'well':1,'also':1,'may':1,'get':1,'one':1,'two':1,'end':1,'day':1,'days':1};
  const freq = {};
  const toks = jdText.toLowerCase().replace(/[^a-z0-9+#. ]/g, ' ').split(/\s+/);
  for (const t0 of toks) {
    const t = t0.replace(/^[.]+|[.]+$/g, '');
    if (t.length < 3 || t.length > 30) continue;
    if (STOP[t]) continue;
    if (/^\d+$/.test(t)) continue;
    freq[t] = (freq[t] || 0) + 1;
  }
  const ranked = Object.keys(freq).sort(function(a, b){ return freq[b] - freq[a]; });
  // keep only meaningfully repeated keywords, cap to 6 to avoid over-narrowing
  const kw = ranked.filter(function(w){ return freq[w] >= 2; }).slice(0, 6);
  if (kw.length) {
    jdTerm = '(' + kw.map(function(w){ return /\s/.test(w) ? '"' + w + '"' : w; }).join(' OR ') + ')';
  }
}

// --- expert noise filter (Boolean Black Belt / SocialTalent best practice) ---
// People-search returns job posts, ATS pages & directories unless we exclude them.
// Site-restricted profile searches (e.g. linkedin.com/in/) already avoid most of
// this, so only apply the noise NOT-block on broad Open Web searches.
let noiseTerm = '';
let cvIntentTerm = '';
if (openWeb) {
  const noise = [
    'intitle:jobs', 'inurl:/jobs/', 'inurl:/careers/', 'inurl:job',
    '"job description"', '"apply now"', '"post a job"', '"we are looking"',
    '"job opening"', 'site:indeed.com', 'site:glassdoor.com',
    'site:naukri.com', 'site:ziprecruiter.com', 'site:lever.co',
    'site:greenhouse.io', 'site:workday.com', 'site:monster.com',
    'site:shine.com', 'site:timesjobs.com', 'site:foundit.in',
    'site:instahyre.com', 'site:cutshort.io', 'site:hirist.com',
    'site:wellfound.com/jobs', 'site:linkedin.com/jobs'
  ];
  noiseTerm = noise.map(function(t){ return '-' + t; }).join(' ');

  // --- CV / personal-blog intent booster (open web only) ---
  // Candidates publish resumes/CVs on personal blogs & doc hosts. Actively TARGET
  // those pages so open-web search surfaces PEOPLE (and their CVs) not job posts.
  // We OR together: (a) resume/CV wording, (b) downloadable CV file types,
  // (c) common personal-blog / CV-hosting domains where people post their CV.
  const cvWords = '("resume" OR "curriculum vitae" OR "cv" OR "portfolio" OR "about me" OR "my work" OR "personal website")';
  const cvFiletypes = '(filetype:pdf OR filetype:doc OR filetype:docx)';
  const cvHosts = '(site:medium.com OR site:github.io OR site:dev.to OR site:hashnode.dev OR site:notion.site OR site:read.cv OR site:standardresume.co OR site:flowcv.com OR site:super.site OR site:substack.com OR site:wordpress.com OR site:blogspot.com OR site:wixsite.com OR site:carrd.co OR site:about.me OR site:behance.net OR site:gitconnected.com OR site:hackernoon.com OR site:drive.google.com OR site:docs.google.com OR site:dropbox.com OR site:1drv.ms)';
  const cvInurl = '(inurl:resume OR inurl:cv OR intitle:resume OR intitle:\"curriculum vitae\" OR inurl:portfolio)';
  cvIntentTerm = '(' + cvWords + ' OR ' + cvFiletypes + ' OR ' + cvHosts + ' OR ' + cvInurl + ')';
}

// --- search region -> Serper gl country code ---
const regionMap = {
  'india':'in','united states':'us','usa':'us','us':'us','america':'us',
  'united kingdom':'gb','uk':'gb','britain':'gb','england':'gb',
  'canada':'ca','australia':'au','germany':'de','france':'fr',
  'netherlands':'nl','holland':'nl','singapore':'sg',
  'united arab emirates':'ae','uae':'ae','dubai':'ae',
  'ireland':'ie','spain':'es','italy':'it','japan':'jp','brazil':'br'
};
const regionRaw = String(form['Search Region'] || '').trim();
let gl = '';
if (regionRaw && !/^global|^all/i.test(regionRaw)) {
  const rkey = regionRaw.toLowerCase().replace(/\s*\(.*\)\s*/, '').trim();
  gl = regionMap[rkey] || '';
}

// --- assemble query ---
const parts = [];
if (sites.length) { parts.push(sites.length > 1 ? '(' + sites.join(' OR ') + ')' : sites[0]); }
if (roleTerm) parts.push(roleTerm);
if (skillsTerm) parts.push(skillsTerm);
if (jdTerm) parts.push(jdTerm);
if (employerTerm) parts.push(employerTerm);
if (eduTerm) parts.push(eduTerm);
if (cvIntentTerm) parts.push(cvIntentTerm);
if (loc) parts.push(q(loc));
if (excludeTerm) parts.push(excludeTerm);
if (noiseTerm) parts.push(noiseTerm);

const query = parts.join(' ').trim();
const PAGES = 3; // Serper: 1 credit per page (each page ~10 results)
const out = [];
for (let pg = 1; pg <= PAGES; pg++) {
  const body = { q: query, page: pg };
  if (gl) body.gl = gl;
  out.push({ json: { q: query, page: pg, pages_total: PAGES, gl: gl || 'global', serper_body: body, jd_keywords: jdTerm || 'none', cv_intent: cvIntentTerm ? 'applied' : 'none', noise_filter: noiseTerm ? 'applied' : 'none', platforms_used: openWeb ? 'Open Web' : (sites.join(', ') || 'default'), excludes_used: excludeTerm || 'none' } });
}
return out;

const cand = $('Attach Resume').item.json || {};
const text = ($json && typeof $json.text === 'string') ? $json.text : '';
const merged = Object.assign({}, cand);
let driveLink = '';
try { const d = $('Save CV to Drive').item.json; driveLink = (d && (d.webViewLink || d.webContentLink)) || ''; } catch (e) { driveLink = ''; }
merged.drive_cv_link = driveLink;
// --- resume contact extraction with name-verification to cut false positives ---
function nameTokens(n) { return String(n || '').toLowerCase().split(/[^a-z]+/).filter(function(t){ return t.length >= 3; }); }
const tokens = nameTokens(merged.candidate_name);
const firstToken = tokens.length ? tokens[0] : '';
const lowText = text.toLowerCase();
// --- directory / bulk-document detection (annual reports, cause lists,
// convocation books, merit/selection lists) contain MANY names+emails and are
// NOT a personal CV even when the candidate's name happens to appear inside. ---
function isDirectoryDoc(t, low) {
  if (!t) return false;
  const em = t.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g) || [];
  const uniq = {}; for (const e of em) uniq[e.toLowerCase()] = 1;
  const emailCount = Object.keys(uniq).length;
  if (emailCount >= 5) return true;                       // many distinct emails = directory
  const phones = t.match(/(?:\+?\d[\d\s().-]{9,}\d)/g) || [];
  if (phones.length >= 8) return true;                    // long phone lists
  const kw = ['annual report','cause list','convocation','gazette','merit list','selection list','provisional list','list of candidates','roll number','roll no','seat number','admit card','result sheet','notice board','shareholders','minutes of the meeting','tender'];
  let hits = 0; for (const k of kw) { if (low.indexOf(k) !== -1) hits++; }
  if (hits >= 1 && emailCount >= 2) return true;          // bulk-doc keyword + multiple emails
  if (t.length > 60000 && emailCount >= 3) return true;   // very long doc w/ several emails
  return false;
}
const directoryDoc = isDirectoryDoc(text, lowText);
// Only trust a scraped resume if the candidate's name STRONGLY appears in it:
// for multi-token names require the first name PLUS at least one other token
// (a shared common surname like "singh" alone is NOT enough); for single-token
// names require that token.
let nameInDoc = false;
if (tokens.length >= 2) {
  const otherHit = tokens.slice(1).some(function(t){ return lowText.indexOf(t) !== -1; });
  nameInDoc = (lowText.indexOf(firstToken) !== -1) && otherHit;
} else if (tokens.length === 1) {
  nameInDoc = lowText.indexOf(firstToken) !== -1;
}
const GENERIC = ['principal','info','admin','administrator','contact','hr','careers','career','office','offices','support','noreply','no-reply','donotreply','enquiry','enquiries','help','sales','webmaster','registrar','dean','placement','placements','mail','email','feedback','hello','team'];
function isGeneric(email) { const local = String(email).split('@')[0].toLowerCase(); return GENERIC.indexOf(local) !== -1; }
// Institutional / government / directory domains that show up in noise PDFs
// (court cause-lists, gazettes, college convocation books) are almost never a
// candidate's personal email — reject them outright.
const NOISE_DOMAIN = /(\.gov(\.[a-z]{2})?$)|(\.nic\.in$)|(\.gov\.in$)|(delhihighcourt)|(\.courts?\.)|(copyright)|(\.mil$)/i;
function isNoiseDomain(email) { const dom = String(email).split('@')[1] || ''; return NOISE_DOMAIN.test(dom); }
// A candidate email must contain the FIRST name, or at least two distinct name
// tokens (kills surname-only false matches like surender.singh for Abhinav Singh).
function localMatchesCandidate(local) {
  if (!tokens.length) return false;
  if (firstToken && local.indexOf(firstToken) !== -1) return true;
  let hits = 0;
  for (const t of tokens) { if (local.indexOf(t) !== -1) hits++; }
  return hits >= 2;
}
if (!merged.email && text && nameInDoc && !directoryDoc) {
  const matches = text.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g) || [];
  let chosen = '';
  for (const em of matches) {
    if (isGeneric(em)) continue;
    if (isNoiseDomain(em)) continue;
    const local = em.split('@')[0].toLowerCase();
    if (localMatchesCandidate(local)) { chosen = em; break; }
  }
