// GitHub native user search (free, uses your GitHub credential -> 5000 req/hr)
const url = 'https://api.github.com/search/users?per_page=30&q=' + encodeURIComponent(q);
return [{ json: { gh_query: q, gh_url: url } }];

// Map GitHub user-search results into the shared organic shape. Search results
// are sparse (login + url); the downstream 'GitHub Enrich' step later fetches
// bio/company/repos for those that survive ranking.
const out = [];
for (const it of $input.all()) {
  const items = (it.json && it.json.items) ? it.json.items : [];
  for (const u of items) {
    const login = String(u.login || '').trim();
    if (!login) continue;
    const link = String(u.html_url || ('https://github.com/' + login));
    out.push({
      title: login + ' (GitHub developer)',
      snippet: 'GitHub developer profile (login: ' + login + ') matching the requested skills. Individual open-source contributor; enrich for bio, company and repositories.',
      link: link
    });
  }
}
return [{ json: { organic: out, source: 'github', results_count: out.length } }];

const out = [];
const seen = {};
let hits = [];
for (const it of $input.all()) { if (it.json && it.json.hits) hits = hits.concat(it.json.hits); }
for (const h of hits) {
  const author = String(h.author || '').trim();
  if (!author || seen[author]) continue;
  seen[author] = true;
  let text = String(h.comment_text || '')
    .replace(/<[^>]+>/g, ' ').replace(/&#x2F;/g, '/').replace(/&#x27;/g, "'")
    .replace(/&gt;/g, '>').replace(/&lt;/g, '<').replace(/&quot;/g, '"').replace(/&amp;/g, '&')
    .replace(/\s+/g, ' ').trim();
  if (text.length < 40) continue;
  if (text.length > 600) text = text.slice(0, 600);
  out.push({ json: { author: author, objectID: h.objectID || '', comment_text: text } });
  if (out.length >= 20) break;
}
return out;

const form = $('Search Criteria').first().json;
let platforms = form['Target Platforms'];
if (!Array.isArray(platforms)) platforms = platforms ? String(platforms).split(',').map(function(s){return s.trim();}).filter(Boolean) : [];
const soSelected = platforms.some(function(p){ return /stack\s*overflow/i.test(String(p)); });
if (!soSelected) return [];
const skillsRaw = String(form['Key Skills & Criteria'] || '').trim();
const role = String(form['Target Role'] || '').trim();
// map common skills -> real Stack Overflow tag slugs
const tagMap = {'spring boot':'spring-boot','springboot':'spring-boot','spring':'spring','react':'reactjs','reactjs':'reactjs','react.js':'reactjs','node':'node.js','nodejs':'node.js','node.js':'node.js','kafka':'apache-kafka','aws':'amazon-web-services','k8s':'kubernetes','kubernetes':'kubernetes','docker':'docker','golang':'go','go':'go','js':'javascript','javascript':'javascript','typescript':'typescript','ts':'typescript','python':'python','java':'java','c#':'c#','.net':'.net','dotnet':'.net','django':'django','flask':'flask','angular':'angular','vue':'vue.js','postgres':'postgresql','postgresql':'postgresql','mysql':'mysql','mongodb':'mongodb'};
const skills = skillsRaw.split(',').map(function(s){return s.trim();}).filter(Boolean);
let tag = '';
for (const s of skills) { const k = s.toLowerCase(); if (tagMap[k]) { tag = tagMap[k]; break; } }
if (!tag && skills.length) { tag = skills[0].toLowerCase().replace(/\s+/g, '-'); }
if (!tag && role) { tag = role.toLowerCase().replace(/\s+/g, '-'); }
if (!tag) return [];
// Stack Exchange API (free, no key for low volume): top answerers for the tag = real skilled people
const url = 'https://api.stackexchange.com/2.3/tags/' + encodeURIComponent(tag) + '/top-answerers/all_time?site=stackoverflow&pagesize=30';
return [{ json: { so_tag: tag, so_url: url } }];

// Map Stack Overflow top-answerers into the shared organic shape for ranking.
const out = [];
for (const it of $input.all()) {
  const items = (it.json && it.json.items) ? it.json.items : [];
  for (const row of items) {
    const u = row.user || {};
    const name = String(u.display_name || '').trim();
    if (!name) continue;
    const link = String(u.link || (u.user_id ? 'https://stackoverflow.com/users/' + u.user_id : ''));
    const rep = (typeof u.reputation === 'number') ? u.reputation : '';
    const posts = (typeof row.post_count === 'number') ? row.post_count : '';
    let snippet = 'Stack Overflow top answerer';
    const ex = [];
    if (rep !== '') ex.push('reputation ' + rep);
    if (posts !== '') ex.push(posts + ' answers in this tag');
    if (ex.length) snippet += ' (' + ex.join(', ') + ')';
    snippet += '. Demonstrated expertise in the requested skill; enrich for role and contact details.';
    out.push({ title: name + ' (Stack Overflow)', snippet: snippet, link: link });
  }
}
return [{ json: { organic: out, source: 'stackoverflow', results_count: out.length } }];
